const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define the area of interest for Upper Arrow Lake, British Columbia, Canada.
    const aoi = ee.Geometry.Rectangle([-118.4, 50.1, -117.8, 50.9]);

    // Define the date and time windows in UTC.
    // Arrow Lake is in Pacific Time (UTC-7 during this period).
    // Morning: 08:00-10:00 PDT -> 15:00-17:00 UTC
    // Afternoon: 13:00-15:00 PDT -> 20:00-22:00 UTC
    const date = '2018-10-22';
    const morningStart = ee.Date(date).advance(15, 'hour');
    const morningEnd = ee.Date(date).advance(17, 'hour');
    const afternoonStart = ee.Date(date).advance(20, 'hour');
    const afternoonEnd = ee.Date(date).advance(22, 'hour');

    // 2. Data Acquisition & Check
    // Use GOES-17 for high temporal resolution (multiple images per day).
    const goesCollection = ee.ImageCollection('NOAA/GOES/17/MCMIPC')
        .filterBounds(aoi)
        .filterDate(date);

    const morningCollection = goesCollection.filterDate(morningStart, morningEnd);
    const afternoonCollection = goesCollection.filterDate(afternoonStart, afternoonEnd);

    const morningSize = morningCollection.size().getInfo();
    const afternoonSize = afternoonCollection.size().getInfo();

    if (morningSize === 0 || afternoonSize === 0) {
        console.log(`Morning image count: ${morningSize}`);
        console.log(`Afternoon image count: ${afternoonSize}`);
        console.log('No GOES images found for one or both time periods.');
        console.log('C1');
        return;
    }

    // 3. Processing
    // Create mean composites for the morning and afternoon periods.
    const morningImage = morningCollection.mean().clip(aoi);
    const afternoonImage = afternoonCollection.mean().clip(aoi);

    // Function to detect low clouds/fog using brightness temperature difference.
    // Low stratus/fog appears warmer in the 3.9µm band than the 11µm band at night.
    // During the day, they reflect solar radiation, appearing cooler (lower temp) in 3.9µm.
    // We use a simple threshold on the 10.3µm band (Band 13) to identify clouds/fog.
    // Cold temperatures (e.g., < 283K or 10°C) indicate cloud tops.
    const detectFog = function(image) {
        // Band 13: 'Clean' IR Longwave Window (~10.3 µm) Brightness Temperature
        const cloudTops = image.select('B13');
        // Threshold for cloud/fog presence (Kelvin).
        const fogMask = cloudTops.lt(283);
        return fogMask.selfMask();
    };

    const morningFog = detectFog(morningImage);
    const afternoonFog = detectFog(afternoonImage);

    // 4. Calculation
    // Calculate the area of fog coverage in each period.
    // The scale of GOES-17 CONUS data is ~2km. We use a larger scale to be safe.
    const scale = 3000;
    const pixelArea = ee.Image.pixelArea();

    const morningFogArea = morningFog.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    }).get('B13');

    const afternoonFogArea = afternoonFog.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    }).get('B13');

    // Execute the calculations.
    const morningResult = morningFogArea.getInfo();
    const afternoonResult = afternoonFogArea.getInfo();

    // 5. Validation & Final Answer
    if (morningResult === null || afternoonResult === null) {
        console.log(`Morning Result: ${morningResult}`);
        console.log(`Afternoon Result: ${afternoonResult}`);
        console.log('Calculation failed, received null result.');
        console.log('C3');
        return;
    }

    // Check for no valid pixels after masking.
    const morningPixelCount = morningFog.reduceRegion({reducer: ee.Reducer.count(), geometry: aoi, scale: scale, maxPixels: 1e9}).get('B13').getInfo();
    const afternoonPixelCount = afternoonFog.reduceRegion({reducer: ee.Reducer.count(), geometry: aoi, scale: scale, maxPixels: 1e9}).get('B13').getInfo();

    if (morningPixelCount === 0 && afternoonPixelCount === 0) {
        console.log(`Morning fog pixels: ${morningPixelCount}`);
        console.log(`Afternoon fog pixels: ${afternoonPixelCount}`);
        console.log('No valid pixels were identified as fog in either period.');
        console.log('C2');
        return;
    }

    const morningAreaSqKm = morningResult / 1e6;
    const afternoonAreaSqKm = afternoonResult / 1e6;

    console.log(`Morning images found: ${morningSize}`);
    console.log(`Afternoon images found: ${afternoonSize}`);
    console.log(`Morning fog coverage (km^2): ${morningAreaSqKm.toFixed(2)}`);
    console.log(`Afternoon fog coverage (km^2): ${afternoonAreaSqKm.toFixed(2)}`);

    if (afternoonAreaSqKm < morningAreaSqKm) {
        console.log('Fog coverage decreased from morning to afternoon.');
        console.log('A');
    } else {
        console.log('Fog coverage did not decrease from morning to afternoon.');
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D');
});
